@startuml

class Home {
  + name : string
}

class Department {
  + name : string
}

class Room {
  + roomNumber : string
}

class Bed {
  + bedNumber : string
}

class Category {
  + name : string
  + price : double
}

class Stay {
  + startDate : date
  + endDate : date
  + status : StayStatus
  + discountRate : float
}

enum StayStatus {
  active
  suspended
  ended
}

class Inhabitant {
  + firstName : string
  + lastName : string
  + identificationData : string
  + registrationDate : date
}

class Registration {
  + questions : string[]
}

class Assessment {
  + needsHelpEating : boolean
  + needsHelpDressing : boolean
  + needsHelpPersonalCare : boolean
  + recommendedStayType : string
}

class WaitingList {
  + position : int
}

class Proposal {
  + proposalDate : date
  + isValid : boolean
}

class Invoice {
  + invoiceNumber : string
  + totalAmount : double
  + outstandingAmount : double
  + isPaid : boolean
}

class CreditNote {
  + creditNoteNumber : string
  + refundAmount : double
}

class PaymentEvent {
  + paymentDate : date
  + amountPaid : double
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" Category
Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" Inhabitant
Inhabitant "1" -- "0..*" WaitingList
Stay "1" -- "1..*" Invoice
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote
Stay "1" -- "0..*" Proposal
Proposal "0..*" -- "1" Inhabitant
Proposal "0..*" -- "1" Stay

@enduml

